#define main inventory_fixture_main
#include "native_source_inventory.cc"
#undef main
#include <filesystem>
#include <google/protobuf/text_format.h>
#include "waymo_open_dataset/protos/motion_metrics.pb.h"
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("args");std::ifstream f(argv[1],std::ios::binary);auto data=read(f,std::filesystem::file_size(argv[1]));waymo::open_dataset::Scenario s;if(!s.ParseFromString(data))throw std::runtime_error("protobuf");known(s);if(s.timestamps_seconds_size()!=91||s.current_time_index()!=10||s.tracks_to_predict_size()==0)throw std::runtime_error("timeline/targets");std::string txt;if(!google::protobuf::TextFormat::PrintToString(s,&txt))throw std::runtime_error("text");std::ofstream(std::string(argv[2])+"/scenario.textproto")<<txt;std::ofstream catalog(std::string(argv[2])+"/expected.tsv");catalog<<"offset\tobject_id\tobject_type\tstep\tvalid\ttruth_x\ttruth_y\tprediction_x\tprediction_y\n";
for(int offset:{0,2}){waymo::open_dataset::ScenarioPredictions p;p.set_scenario_id(s.scenario_id());std::set<int> ids;for(auto&target:s.tracks_to_predict()){if(target.track_index()<0||target.track_index()>=s.tracks_size())throw std::runtime_error("native target index");auto&t=s.tracks(target.track_index());if(!ids.insert(t.id()).second||!t.states(10).valid())throw std::runtime_error("target eligibility");auto*mode=p.add_multi_modal_predictions()->add_joint_predictions();mode->set_confidence(1);auto*trajectory=mode->add_trajectories();trajectory->set_object_id(t.id());for(int j=0;j<16;j++){auto&state=t.states(15+j*5);trajectory->add_center_x(state.center_x()+offset);trajectory->add_center_y(state.center_y());catalog.precision(17);catalog<<offset<<'\t'<<t.id()<<'\t'<<t.object_type()<<'\t'<<j<<'\t'<<state.valid()<<'\t'<<state.center_x()<<'\t'<<state.center_y()<<'\t'<<trajectory->center_x(j)<<'\t'<<trajectory->center_y(j)<<'\n';}}if(!google::protobuf::TextFormat::PrintToString(p,&txt))throw std::runtime_error("prediction text");std::ofstream(std::string(argv[2])+"/predictions-"+std::to_string(offset)+".textproto")<<txt;}
std::ofstream(std::string(argv[2])+"/config.textproto")<<"track_steps_per_second: 10 prediction_steps_per_second: 2 track_history_samples: 10 track_future_samples: 80 max_predictions: 1 step_configurations { measurement_step: 15 lateral_miss_threshold: 3 longitudinal_miss_threshold: 6 }";std::cout<<"NATIVE METRIC FIXTURES "<<s.scenario_id()<<" TARGETS "<<s.tracks_to_predict_size()<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
